def encode_dimension_state(state):
    if state == "Supported":
        return 1, 1

    if state == "Absent":
        return 0, 1

    if state == "Unavailable":
        return 0, 0

    raise ValueError(
        f"Unexpected SE-BRL state: {state}"
    )

